<script setup>
import { onMounted, reactive } from 'vue';import { api } from '../api.js'
const props=defineProps({settings:Object,update:Object});defineEmits(['save-telegram','test-telegram','save-updates','check-update','apply-update'])
const tg=reactive({botToken:'',chatId:props.settings.telegram.chatId||'',enabled:!!props.settings.telegram.enabled,showBuyLink:props.settings.telegram.showBuyLink!==false});const up=reactive({repository:props.settings.updates.repository||'',branch:props.settings.updates.branch||'main'});const previews=reactive({restock:'正在生成预览...',soldout:'正在生成预览...'})
onMounted(async()=>{const clean=t=>t.replace(/<[^>]*>/g,'');try{previews.restock=clean((await api('/api/telegram/preview',{method:'POST',body:'{}'})).text);previews.soldout=clean((await api('/api/telegram/preview',{method:'POST',body:JSON.stringify({status:'sold_out'})})).text)}catch{}})
</script>
<template><section class="setting-grid"><form class="panel settings-card" @submit.prevent="$emit('save-telegram',{...tg})"><h2>Telegram 频道通知</h2><p>Bot 必须是目标频道管理员，才能发送及编辑补货卡片。</p><div class="field"><label>Bot Token</label><input v-model="tg.botToken" type="password" :placeholder="settings.telegram.botTokenConfigured?'已保存，留空则不修改':'123456:ABC...'"></div><div class="field"><label>频道 Chat ID</label><input v-model="tg.chatId" placeholder="-1001234567890"></div><label class="check"><input type="checkbox" v-model="tg.enabled"> 开启 TG 通知</label><label class="check"><input type="checkbox" v-model="tg.showBuyLink"> 在卡片中展示购买链接</label><div class="controls"><button class="button">保存设置</button><button class="button secondary" type="button" @click="$emit('test-telegram')">测试 TG 连通性</button></div></form><aside class="panel settings-card"><h2>卡片预览</h2><p>库存由商家页面数据决定：有数量即显示，无数量则自动隐藏。</p><p class="preview-label">补货卡片</p><pre class="preview">{{previews.restock}}</pre><p class="preview-label">售罄卡片</p><pre class="preview">{{previews.soldout}}</pre></aside></section>
<section class="setting-grid update-section"><form class="panel settings-card" @submit.prevent="$emit('save-updates',{...up})"><h2>在线更新</h2><p>systemd 部署可直接从 GitHub 拉取更新；Docker 模式应拉取新的 GHCR 镜像。</p><div class="field"><label>GitHub 仓库</label><input v-model="up.repository" placeholder="owner/repository"></div><div class="field"><label>发布分支</label><input v-model="up.branch"></div><button class="button">保存更新来源</button></form><aside class="panel settings-card"><h2>版本状态</h2><p>{{update?.message||'正在检查 GitHub 版本...'}}</p><div class="controls"><button class="button secondary" type="button" @click="$emit('check-update')">检查更新</button><button v-if="update?.updateAvailable&&update?.deployReady" class="button" type="button" @click="$emit('apply-update')">在线更新并重启</button></div><p class="hint" v-if="update?.localRevision">当前 {{update.localRevision.slice(0,8)}} · 远端 {{update.remoteRevision?.slice(0,8)||'未找到'}}</p></aside></section></template>
